
/* ================= FUNNEL MAPPER PRO inside the ecosystem ================= */
const FMPF=[['q1','Fitness quiz funnel','Harry Kaye PT','hk','Live','$6,032','13.4x'],['w1','Webinar funnel','Mindful Money Co','mm','Planned','$9,800','4.1x'],['d1','DFY application funnel',null,null,'Live','$12,400','6.2x'],['c1','Funnel Done Right Challenge',null,null,'Draft','$3,200','—']];
const FNV=[['fmp/home','Dashboard','home'],['fmp/funnels','Funnels','funnels'],['fmp/templates','Templates','copy'],['fmp/trash','Trash','trash'],['fmp/settings','Settings','gear']];
const fShell=(cur,body,crumbs)=>shell('fmp',{nav:FNV,cur,body,crumbs:crumbs||[['Funnel Mapper Pro']],barRight:`<button class="btn primary sm" data-act="toast:New funnel: choose internal or a client, then blank or a template.">${ic('plus',16,'',2.2)}<span class="hide-m">New funnel</span></button>`});
const ftbl=L=>`<div class="tblwrap"><table class="tbl"><thead><tr><th>Funnel</th><th>Belongs to</th><th>Status</th><th>Revenue / mo</th><th>ROAS</th></tr></thead><tbody>${L.map(([id,n,cl,cid,s,r,ro])=>`<tr data-row="${n} ${cl||''}"><td class="t1"><a class="fname" href="#/fmp/funnel/${id}">${ic('funnels')}${n}</a></td><td data-l="Belongs to">${cl?`<a class="rel client" href="#/clients/c/${cid}/overview">${ic('clients',13)}${cl}</a>`:`<span class="rel">${mark(org(),16)} ${oname()} (internal)</span>`}</td><td data-l="Status"><span class="pill ${s==='Live'?'blue':''}">${s}</span></td><td data-l="Revenue" class="mono">${r}</td><td data-l="ROAS" class="mono">${ro}</td></tr>`).join('')}</tbody></table></div>`;
VIEWS.fmp=p=>{const pg=p[0]||'home';if(org()==='aurj')return fShell('fmp/home',emptyS(plate(app('fmp'),64),'Funnel Mapper Pro isn’t set up in Aurj','It’s on for Layer2Funnels only.',`<button class="btn primary" data-act="org:l2f">Switch to Layer2Funnels</button>`));
if(pg==='funnel')return fmpEditor(p[1]||'q1');
if(pg==='home')return fShell('fmp/home',`<div class="pagehead"><div><p class="over">Funnel Mapper Pro · ${oname()}</p><h1 class="h1">Map, model and forecast</h1></div></div><div class="kpis big">${[['3','Live funnels'],['$21.6K','Modelled revenue / mo'],['2','Client funnels'],['1','Draft']].map(([b,s])=>`<div><b>${b}</b><span>${s}</span></div>`).join('')}</div><div class="split" style="margin-top:20px"><section class="panel"><div class="sec-h"><h2>Recent funnels</h2><a class="linkbtn" href="#/fmp/funnels">All</a></div>${ftbl(FMPF.slice(0,3))}</section><section class="panel" style="padding:18px 20px"><p class="sec-t" style="margin-top:0">${ic('info',16)}Clients come from Clients</p><p class="tx2" style="font-size:14px">A funnel is either internal to ${oname()} or belongs to a client from the Clients app. Client details, contacts and files stay in Clients; maps, numbers and scenarios stay here.</p><a class="btn ghost sm" style="margin-top:10px" href="#/clients/pipeline">${plate(app('clients'),20)}Open Clients</a></section></div>`);
if(pg==='funnels')return fShell('fmp/funnels',`${head('Funnels','Internal funnels first, then client funnels. A client’s funnels also appear on that client’s page.')}<div class="toolbar">${vsw([['all','All'],['int','Internal'],['cl','Clients']],'all','noop')}<label class="inp grow">${ic('search',16)}<input placeholder="Filter funnels" data-filter></label><select class="sel"><option>Any client</option><option>Harry Kaye PT</option><option>Mindful Money Co</option></select></div>${ftbl(FMPF)}`,[['Funnel Mapper Pro'],['Funnels']]);
if(pg==='templates')return fShell('fmp/templates',`${head('Templates','Start from a proven funnel shape.')}<div class="cardgrid">${['Quiz funnel','Webinar funnel','Application funnel','Tripwire funnel','Challenge funnel'].map(n=>`<a class="card fmpcard" href="#/fmp/funnel/q1"><span class="mini-map"><i></i><i></i><i></i><i></i></span><h3>${n}</h3></a>`).join('')}</div>`,[['Funnel Mapper Pro'],['Templates']]);
if(pg==='trash')return fShell('fmp/trash',head('Trash','Deleted funnels, restorable for 30 days.')+'<p class="hint">Nothing in trash.</p>',[['Funnel Mapper Pro'],['Trash']]);
return fShell('fmp/settings',`${head('Settings','Funnel Mapper Pro’s own defaults. Team, workspace and access move to Office › Admin when it joins the ecosystem.')}<section class="panel" style="padding:20px;max-width:640px"><div class="field"><label>Default currency</label><select><option>USD</option><option>GBP</option><option>PKR</option></select></div><div class="field"><label>Revenue counts as</label><select><option>First payment</option><option>Lifetime value</option></select></div><div class="tg-row">Show numbers on the map by default<button class="toggle" role="switch" aria-checked="true" data-act="tgl" aria-label="Numbers"></button></div></section>`,[['Funnel Mapper Pro'],['Settings']])};
function fmpEditor(id){const f=FMPF.find(x=>x[0]===id)||FMPF[0];const N=[['Instagram ads','Traffic',2300,'src',40,60],['Fitness quiz','Page · 45%',1035,'pg',250,60],['Your result','Page · 70%',725,'pg',460,30],['Book a call','Page · 30%',217,'pg',670,60],['Discovery call','Event · 41%',89,'ev',880,30],['12-week coaching','Offer · $497',89,'of',880,190]];
return `<div class="fmp-wrap" data-app="fmp">${focusBar('fmp',{title:`<b>${f[1]}</b>`,sub:f[2]?`Client: ${f[2]} · from Clients`:`${oname()} · internal`,back:'fmp/funnels',right:`${vsw([['map','Map'],['rep','Reports']],'map','noop')}<span class="hide-m">${avs(['TR','UM'])}</span><button class="btn ghost sm hide-m" data-act="toast:Present: walks through each frame.">${ic('play',16)}Present</button><button class="btn primary sm" data-act="toast:Share link: view-only, numbers on or off, optional expiry.">${ic('share',16)}Share</button>`})}
<div class="fmp-body"><aside class="fmp-lib"><label class="inp">${ic('search',16)}<input placeholder="Search 170 blocks"></label><p class="over">Recent</p>${['Facebook ads','Quiz page','Order form','Upsell','Email'].map(n=>`<button class="fmp-blk">${ic('funnels',16)}${n}</button>`).join('')}<p class="over">Traffic · Pages · Offers · Actions · Logic · Notes</p></aside>
<div class="fmp-canvas"><svg class="fmp-edges" viewBox="0 0 1060 300" preserveAspectRatio="xMinYMin meet">${N.slice(0,-1).map((a,i)=>{const b=N[i+1];return `<path d="M${a[4]+150} ${a[5]+34} C ${a[4]+180} ${a[5]+34}, ${b[4]-30} ${b[5]+34}, ${b[4]} ${b[5]+34}" stroke-width="${Math.max(2,a[2]/180)}"/>`}).join('')}<path d="M780 ${N[3][5]+60} C 790 260, 820 290, 880 ${N[5][5]+34}" class="no"/></svg>${N.map(([n,s,v,k,x,y])=>`<div class="fmp-node ${k}" style="left:${x}px;top:${y}px"><b>${n}</b><small>${s}</small><span class="mono">${v.toLocaleString()}</span></div>`).join('')}</div>
<aside class="fmp-insp"><div class="vsw">${['Model','Simulate','Track'].map((t,i)=>`<button aria-pressed="${!i}">${t}</button>`).join('')}</div><p class="over" style="margin-top:12px">Fitness quiz</p><div class="field"><label>Conversion</label><input value="45%"></div><div class="field"><label>Visitors</label><input value="2,300" readonly></div><div class="notice plain" style="font-size:13px">${ic('alert',16)}<span><b>Key leak.</b> 1,265 people leave at the quiz. 10% better here adds about $749 a month.</span></div></aside></div>
<div class="fmp-kpi">${[['Traffic','2,300'],['Leads','1,035'],['Customers','89.1'],['Revenue','$6,032'],['Profit','$5,582'],['ROAS','13.4x']].map(([l,v])=>`<div><small>${l}</small><b>${v}</b></div>`).join('')}<button class="chip">6 more</button><button class="chip warn">${ic('alert',14)}2 checks</button></div></div>`}
SEARCH.push(()=>org()==='l2f'?FMPF.map(f=>({app:'fmp',t:f[1],s:(f[2]||'Internal')+' · '+f[4],href:'fmp/funnel/'+f[0]})):[]);

/* ================= LAYER 2 AGENTS ================= */
const ANV=[['agents/home','Agents','agents'],['agents/meetings','Meeting Intelligence','mic',null,null,'Meetings'],['agents/ask','Ask','sparkle'],['agents/settings','Access & settings','shield',null,null,'Settings']];
const aShell=(cur,body,crumbs)=>shell('agents',{nav:ANV,cur,body,crumbs:crumbs||[['Layer 2 Agents']],sideMid:`<div class="notice plain" style="margin:12px 8px;font-size:12.5px">${ic('lock',14)}<span>Preview. No agent runs until you approve the provider, cost and data rules.</span></div>`});
const MEET=[['m1','Weekly team call','Today, 10:00','42 min','Team · Urdu + English',4],['m2','Kick-off with Harry Kaye','Mon, 15:00','58 min','Client · English',6],['m3','Funnel Challenge podcast ep. 3','Last week','31 min','Podcast',2]];
VIEWS.agents=p=>{const pg=p[0]||'home';
if(pg==='home')return aShell('agents/home',`${head('Layer 2 Agents','Helpers that work inside your apps, only with what you can already see.')}<div class="cardgrid">${[['mic','Meeting Intelligence','Listens to meetings, calls, podcasts or lectures. Saves the audio, transcript and notes to Drive.','agents/meetings','#7E5BF2','Designed'],['sparkle','Ask','Answers questions from your own work: “What are my tasks today?”','agents/ask','#2B63F6','Designed'],['plus','Your next agent','Content drafts, client follow-ups and more, one at a time.','agents/home','#7C818D','Later']].map(([i,t,d,h,c,s])=>`<a class="card" href="#/${h}"><span class="wic" style="--c:${c}">${ic(i,22)}</span><h3>${t}</h3><p>${d}</p><div class="foot"><span class="pill">${s}</span></div></a>`).join('')}</div>`);
if(pg==='meetings')return aShell('agents/meetings',`${head('Meeting Intelligence','Record or upload a conversation. Get the audio, a transcript with speakers, and clear notes, filed in Drive.',`<a class="btn primary" href="#/agents/meeting/new">${ic('mic',18)}New session</a>`)}<div class="tblwrap"><table class="tbl"><thead><tr><th>Session</th><th>When</th><th>Length</th><th>Type</th><th>Action items</th></tr></thead><tbody>${MEET.map(([id,n,w,l,t,a])=>`<tr><td class="t1"><a class="fname" href="#/agents/meeting/${id}">${ic('wave')}${n}</a></td><td data-l="When">${w}</td><td data-l="Length">${l}</td><td data-l="Type">${t}</td><td data-l="Action items">${a}</td></tr>`).join('')}</tbody></table></div>`,[['Layer 2 Agents'],['Meeting Intelligence']]);
if(pg==='meeting'&&p[1]==='new')return aShell('agents/meetings',`${back('agents/meetings','Sessions')}<div class="meet-new"><div class="rec"><button class="recbtn" data-act="recstart" aria-label="Start recording">${ic('mic',40)}</button><h2 class="h2" id="recst">Ready to listen</h2><div class="wavebars" aria-hidden="true">${Array.from({length:32},(_,i)=>`<i style="--d:${(i%7)*.1}s"></i>`).join('')}</div><p class="hint">Uses this device’s microphone. Everyone in the room should know you’re recording.</p><div class="chiprow" style="justify-content:center"><button class="chip">${ic('upload',14)}Upload a recording</button><button class="chip" data-act="toast:Joining Zoom calls needs an approved integration.">${ic('zoom',14)}Join a Zoom call</button></div></div>
<section class="panel" style="padding:20px"><p class="sec-t" style="margin-top:0">This session</p><div class="field"><label>Name</label><input value="Weekly team call"></div><div class="field"><label>Organization</label><select><option>Layer2Funnels</option><option>Aurj</option></select></div><div class="field"><label>Language</label><select><option>Urdu + English (mixed)</option><option>English</option><option>Urdu</option></select></div><p class="sec-t">Save to Drive</p>${[['Audio (MP3)',1],['Transcript',1],['Meeting notes',1],['Action items to Tasks',0]].map(([l,on])=>`<div class="tg-row">${l}<button class="toggle" role="switch" aria-checked="${!!on}" data-act="tgl" aria-label="${l}"></button></div>`).join('')}<p class="hint">Folder: Drive › Meetings › 2026-11-12 Weekly team call</p></section></div>`,[['Layer 2 Agents'],['New session']]);
if(pg==='meeting'){const m=MEET.find(x=>x[0]===p[1])||MEET[0];const t=p[2]||'notes';return aShell('agents/meetings',`${back('agents/meetings','Sessions')}<div class="ph" style="margin-top:10px"><span class="pbig" style="--c:#7E5BF2">${ic('wave',22,'',2)}</span><div><h1>${m[1]}</h1><div class="meta">${m[2]} · ${m[3]} · ${m[4]}</div></div><div class="acts"><a class="btn ghost sm" href="#/drive/home">${plate(app('drive'),18)}Open folder</a></div></div><div class="audio">${ic('play',20)}<div class="wavebars static">${Array.from({length:60},(_,i)=>`<i style="height:${6+Math.abs(Math.sin(i*1.7))*26}px"></i>`).join('')}</div><span class="mono">12:04 / ${m[3]}</span></div>${tabs([['notes','Notes'],['transcript','Transcript'],['actions','Action items',m[5]]],t,`agents/meeting/${m[0]}/`)}
${t==='notes'?`<article class="docpage" style="min-height:0"><h2 style="margin-top:0">Summary</h2><p>The team agreed to launch the Harry Kaye quiz funnel on 28 Nov. Copy is one day behind; design will catch up by Friday.</p><h2>Decisions</h2><ul><li>Keep “get fit” language from Harry’s interview.</li><li>Funnel Challenge moves to January.</li></ul><h2>Risks</h2><ul><li>GHL calendar sync not tested yet.</li></ul></article>`:''}
${t==='transcript'?`<div class="transcript">${[['TR','Tabish','Chalo, quiz funnel ka status batao.','00:12'],['SN','Sana','Questions v2 almost done, Friday tak Harry ko bhej dungi.','00:20'],['BK','Bilal','The GHL calendar sync still needs a test.','00:41']].map(([k,n,x,w])=>`<div class="tline">${av(k)}<div><b>${n}</b> <small class="mono muted">${w}</small><p>${x}</p></div><button class="iconbtn" aria-label="Rename speaker" data-act="toast:Rename this speaker everywhere.">${ic('edit',14)}</button></div>`).join('')}</div>`:''}
${t==='actions'?`<div class="checkl">${['Send quiz questions v2 to Harry · Sana · Fri','Test GHL calendar sync · Bilal · Wed','Move Challenge launch to January · Tabish'].map(x=>`<div class="row"><button class="cbx" role="checkbox" aria-checked="false" data-act="sub"><i>${ic('check',14,'',3)}</i></button><div class="main"><b>${x}</b></div><button class="btn quiet sm" data-act="toast:Created in Tasks with a link back to this meeting.:ok">→ Task</button></div>`).join('')}</div>`:''}`,[['Layer 2 Agents'],['Meeting Intelligence','agents/meetings'],[m[1]]])}
if(pg==='ask')return aShell('agents/ask',`<div class="ask"><div class="ask-log"><div class="msg me">What are my tasks today?</div><div class="msg ai"><p>You have <b>4 things today</b> in ${oname()}:</p><ol><li>Write results page copy · Projects · Harry Kaye quiz funnel</li><li>Check GHL calendar sync · Tasks · Build team</li><li>Post update on “40 booked calls” · Planner</li><li>Approve email sequence v2 · <b>overdue</b></li></ol><small class="muted">Sources: Projects, Tasks, Planner. Only items you can open.</small><div class="chiprow"><a class="chip" href="#/office/home">Open My day</a></div></div></div><div class="compose ask-in"><textarea placeholder="Ask about your work in ${oname()}…" aria-label="Ask"></textarea><button class="btn primary" data-act="toast:Preview: the assistant isn’t connected yet.">${ic('send',18)}</button></div><p class="hint" style="text-align:center">Preview. Answers come only from records you can open, and every answer shows its sources.</p></div>`,[['Layer 2 Agents'],['Ask']]);
return aShell('agents/settings',`${head('Access & settings','What each agent may read, where it saves, and who may run it.')}<div class="tblwrap"><table class="tbl"><thead><tr><th>Agent</th><th>Can read</th><th>Can write</th><th>Who can run it</th><th>Organizations</th></tr></thead><tbody><tr><td class="t1">Meeting Intelligence</td><td data-l="Can read">Microphone or uploaded audio only</td><td data-l="Can write">Drive › Meetings, Tasks (if on)</td><td data-l="Who">Owners, Admins</td><td data-l="Orgs">Layer2Funnels, Aurj (separately)</td></tr><tr><td class="t1">Ask</td><td data-l="Can read">What the asking person can open</td><td data-l="Can write">Nothing</td><td data-l="Who">Everyone</td><td data-l="Orgs">The current one</td></tr></tbody></table></div><div class="notice" style="margin-top:14px">${ic('alert',18)}<span><b>Needs your approval before go-live:</b> the speech and AI provider, monthly cost cap, data retention (recommended: audio 30 days, transcript and notes kept), and consent wording.</span></div>`,[['Layer 2 Agents'],['Access & settings']])};
ACT.recstart=(v,t)=>{t.classList.toggle('on');const on=t.classList.contains('on');$('#recst').textContent=on?'Listening… 00:04 · Sana is speaking':'Paused';$('.wavebars')?.classList.toggle('live',on)};

